    private String promptIdentity()throws Exception{return main(()->{Method method=MainActivity.class.getDeclaredMethod("promptPageIdentity");method.setAccessible(true);return (String)method.invoke(activity);});}
    private void supplyThreadMetadata()throws Exception{main(()->{cn.ngapure.app.NgaApi.Topic topic=new cn.ngapure.app.NgaApi.Topic();topic.tid="7000000001";topic.fid="650";topic.title="合成线程元数据";set(field(activity,"current"),"topic",topic);return null;});}
    private void observeThreadMetadata()throws Exception{stage="observeThreadMetadata";screen("thread","7000000001",2);NativeGlassDialog dialog=openSearchWith("synthetic-same-thread");String before=promptIdentity();supplyThreadMetadata();String after=promptIdentity();boolean sameRoute=main(()->"thread".equals(field(field(activity,"current"),"kind"))&&"7000000001".equals(field(field(activity,"current"),"id"))&&(Integer)field(field(activity,"current"),"page")==2);main(()->{dialog.getButton(Dialog.BUTTON_POSITIVE).performClick();return null;});report.put("threadRouteUnchangedWhenMetadataArrives",sameRoute).put("sameThreadMetadataChangedPromptIdentity",!before.equals(after)).put("queryAcceptedWithoutNewSubmitGuard","search".equals(kind())).put("expectedMetadataIdentityRegressionObserved",sameRoute&&!before.equals(after)).put("observationOnly",true).put("completed",true);}
