        main(()->{input(controls.getWindow().getDecorView()).setError(null);controls.getButton(Dialog.BUTTON_NEUTRAL).performClick();return null;});check("controlUsernameRemainsEditableWithError",main(()->controls.isShowing()&&input(controls.getWindow().getDecorView()).getError()!=null));
