        screen("settings","",1);NativeGlassDialog old=openSearchWith("synthetic-old-dialog");NativeGlassDialog fresh=openSearchWith("synthetic-new-dialog");main(()->{old.getButton(Dialog.BUTTON_POSITIVE).performClick();return null;});check("oldDialogCallbackCannotNavigateOrCloseNewPrompt",main(()->"settings".equals(field(field(activity,"current"),"kind"))&&field(activity,"searchDialog")==fresh&&fresh.isShowing()));
