        main(()->{Bundle saved=new Bundle();activity.onSaveInstanceState(saved);Bundle nav=saved.getBundle("ngapure_navigation_v1");Method entryMethod=MainActivity.class.getDeclaredMethod("navigationEntry",field(activity,"current").getClass());entryMethod.setAccessible(true);Object expected=entryMethod.invoke(activity,field(activity,"current"));Method restore=MainActivity.class.getDeclaredMethod("restoreSubForumsExpanded",Bundle.class,expected.getClass(),int.class);restore.setAccessible(true);
            nav.putString("current_subforums_expanded","true");check("expansionRequiresBooleanType",Boolean.FALSE.equals(restore.invoke(activity,saved,expected,-1)));nav.putBoolean("current_subforums_expanded",true);String[] route=nav.getStringArray("current");String[] wrong=route.clone();wrong[1]="754";nav.putStringArray("current",wrong);check("expansionCannotRestoreOntoDifferentForum",Boolean.FALSE.equals(restore.invoke(activity,saved,expected,-1)));nav.putStringArray("current",route);nav.putInt("backCount",33);check("expansionRejectsOversizedNavigationState",Boolean.FALSE.equals(restore.invoke(activity,saved,expected,-1)));return null;});
        main(()->{Class<?> type=field(activity,"current").getClass();Constructor<?> constructor=type.getDeclaredConstructor(String.class,String.class,String.class,int.class);constructor.setAccessible(true);Object child=constructor.newInstance("forum","754","合成子版块",1);Method go=MainActivity.class.getDeclaredMethod("go",type,boolean.class);go.setAccessible(true);go.invoke(activity,child,true);return null;});check("newChildForumStartsCollapsed",main(()->Boolean.FALSE.equals(field(field(activity,"current"),"subForumsExpanded"))));recreate();check("expandedParentInBackStackSurvivesRecreate",main(()->{Object parent=((java.util.Deque<?>)field(activity,"back")).peek();return parent!=null&&"650".equals(field(parent,"id"))&&Boolean.TRUE.equals(field(parent,"subForumsExpanded"));}));invoke("onBackPressed",new Class<?>[0]);check("returningToParentKeepsExpansion",main(()->"650".equals(field(field(activity,"current"),"id"))&&Boolean.TRUE.equals(field(field(activity,"current"),"subForumsExpanded"))));main(()->{set(field(activity,"current"),"subForumsExpanded",false);return null;});recreate();check("collapsedForumAlsoSurvivesRecreate",main(()->Boolean.FALSE.equals(field(field(activity,"current"),"subForumsExpanded"))));
